import type { SynapseEnhancedHttpClient } from "../utils/http.ts";
import { validateUserId, validateNumber } from "../utils/validator.ts";
import { SynapseAdminApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export interface ICreatePrivateChatParams {
    target_user_id: string;
    is_encrypted?: boolean;
    ttl?: number;
}

export interface IPrivateChatListParams {
    page?: number;
    page_size?: number;
}

export interface IPrivateChatAdminDetail {
    room_id: string;
    name?: string;
    is_public: boolean;
    member_count: number;
    created_at: string;
    creator_id: string;
}

export interface IPrivateChatAdminResult {
    room_id: string;
    status: string;
}

export interface IPrivateChatListResult {
    rooms: IPrivateChatAdminDetail[];
    total: number;
    page: number;
    page_size: number;
}

export class PrivateChatAdminApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async createPrivateChat(params: ICreatePrivateChatParams): Promise<{
        room_id: string;
        is_encrypted: boolean;
        ttl: number;
    }> {
        validateUserId(params.target_user_id);
        if (params.ttl !== undefined) {
            validateNumber(params.ttl, "ttl", { min: 1, max: 31536000 });
        }

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
                is_encrypted: boolean;
                ttl: number;
            };
            error?: string;
        }>(`${SynapseAdminApi.PRIVATE_CHAT}/create`, {
            target_user_id: params.target_user_id,
            is_encrypted: params.is_encrypted ?? true,
            ttl: params.ttl ?? 86400,
        });

        const data = handleApiResponse(response, "Failed to create private chat");

        return {
            room_id: data.room_id,
            is_encrypted: data.is_encrypted,
            ttl: data.ttl,
        };
    }

    public async listPrivateChats(params?: IPrivateChatListParams): Promise<IPrivateChatListResult> {
        if (params?.page !== undefined) {
            validateNumber(params.page, "page", { min: 1 });
        }
        if (params?.page_size !== undefined) {
            validateNumber(params.page_size, "page_size", { min: 1, max: 100 });
        }

        const queryParams: Record<string, number> = {};
        if (params?.page !== undefined) queryParams.page = params.page;
        if (params?.page_size !== undefined) queryParams.page_size = params.page_size;

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                rooms?: IPrivateChatAdminDetail[];
                total?: number;
                page?: number;
                page_size?: number;
            };
            error?: string;
        }>(`${SynapseAdminApi.PRIVATE_CHAT}/list`, queryParams);

        const data = handleApiResponse(response, "Failed to list private chats");

        return {
            rooms: data.rooms || [],
            total: data.total || 0,
            page: data.page || 1,
            page_size: data.page_size || 20,
        };
    }

    public async getPrivateChatDetail(roomId: string): Promise<IPrivateChatAdminDetail | null> {
        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: IPrivateChatAdminDetail;
                error?: string;
            }>(`${SynapseAdminApi.PRIVATE_CHAT}/${encodeURIComponent(roomId)}`);

            return handleApiResponse(response, "Failed to get private chat detail");
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("not found") || error.message.includes("not exist"))
            ) {
                return null;
            }
            throw error;
        }
    }

    public async deletePrivateChat(roomId: string): Promise<IPrivateChatAdminResult> {
        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
                status: string;
            };
            error?: string;
        }>(`${SynapseAdminApi.PRIVATE_CHAT}/${encodeURIComponent(roomId)}/delete`, {});

        const data = handleApiResponse(response, "Failed to delete private chat");

        return {
            room_id: data.room_id,
            status: data.status,
        };
    }
}
